import React, { lazy, Suspense, useEffect, useState } from 'react';

const Chatbot = lazy(() => import('./Chatbot/Chatbot'));

const IDLE_TIMEOUT_MS = 4000;
const FALLBACK_DELAY_MS = 2500;

function scheduleDeferredMount(onReady) {
  if (typeof window === 'undefined') return () => {};

  let cancelled = false;
  const run = () => {
    if (!cancelled) onReady();
  };

  const onFirstInput = () => {
    window.removeEventListener('pointerdown', onFirstInput, true);
    window.removeEventListener('keydown', onFirstInput, true);
    run();
  };

  window.addEventListener('pointerdown', onFirstInput, { capture: true, passive: true });
  window.addEventListener('keydown', onFirstInput, { capture: true });

  let idleId;
  let idleViaCallback = false;
  if (typeof window.requestIdleCallback === 'function') {
    idleViaCallback = true;
    idleId = window.requestIdleCallback(run, { timeout: IDLE_TIMEOUT_MS });
  } else {
    idleId = window.setTimeout(run, FALLBACK_DELAY_MS);
  }

  return () => {
    cancelled = true;
    window.removeEventListener('pointerdown', onFirstInput, true);
    window.removeEventListener('keydown', onFirstInput, true);
    if (idleViaCallback) {
      window.cancelIdleCallback(idleId);
    } else {
      window.clearTimeout(idleId);
    }
  };
}

/** Loads chatbot after idle or first user gesture — keeps main thread free for INP. */
export default function DeferredChatbot() {
  const [ready, setReady] = useState(false);

  useEffect(() => scheduleDeferredMount(() => setReady(true)), []);

  if (!ready) return null;

  return (
    <Suspense fallback={null}>
      <Chatbot />
    </Suspense>
  );
}
